begin;
do $$declare own uuid;student uuid;os uuid;ss uuid;s uuid;r uuid;roleid uuid;v jsonb;code text;begin
 select owner_id into own from acc_private.owner_setup where id;select id into student from public.acc_profiles where id<>own and role='student' and not suspended limit 1;select id into os from auth.sessions where user_id=own limit 1;select id into ss from auth.sessions where user_id=student limit 1;
 if own is null or student is null or os is null or ss is null then raise exception 'Two real existing account sessions required';end if;
 perform set_config('sv.student',student::text,true);perform set_config('sv.ss',ss::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 begin perform public.acc_call('serverCreate','{"name":"Forbidden pilot server"}');raise exception 'Pilot gate bypass';exception when others then if sqlerrm='Pilot gate bypass' then raise;end if;end;
 update acc_private.social_release set enabled=true where id;
 s:=(public.acc_call('serverCreate','{"name":"Rollback server","visibility":"private"}')->>'server')::uuid;
 select room into r from acc_private.server_channels where server=s;perform set_config('sv.server',s::text,true);perform set_config('sv.room',r::text,true);
 if (select role from public.acc_profiles where id=student)<>'student' or acc_private.is_owner() then raise exception 'Server owner gained platform power';end if;
 if not acc_private.access(r) then raise exception 'Server creator lacks access';end if;
 perform public.acc_call('serverSave',jsonb_build_object('server',s,'name','Rollback server','description','Test','icon','leaf','color','#aaccee','visibility','public','category','Gaming'));
 if jsonb_array_length(public.acc_call('serverDirectory'))<>0 then raise exception 'Unapproved server listed';end if;
 begin perform public.acc_call('serverApprove',jsonb_build_object('server',s,'approved',true));raise exception 'Student approved directory';exception when others then if sqlerrm='Student approved directory' then raise;end if;end;
 begin perform public.acc_call('serverRoleSave',jsonb_build_object('server',s,'name','Exploit','color','#aaccee','permissions','{"platform_owner":true}'::jsonb));raise exception 'Platform permission accepted';exception when others then if sqlerrm='Platform permission accepted' then raise;end if;end;
 perform public.acc_call('serverCreate','{"name":"Rate server 2"}');perform public.acc_call('serverCreate','{"name":"Rate server 3"}');
 begin perform public.acc_call('serverCreate','{"name":"Rate server 4"}');raise exception 'Creation rate limit failed';exception when others then if sqlerrm='Creation rate limit failed' then raise;end if;end;
 -- Use the real student as a member, owner as platform reviewer; test channel overrides without a third fake student.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('serverApprove',jsonb_build_object('server',s,'approved',true));
 if jsonb_array_length(public.acc_call('serverDirectory'))<>1 then raise exception 'Approved listing missing';end if;
 update public.acc_servers set owner=own where id=s;insert into acc_private.server_members(server,person) values(s,own) on conflict do nothing;
 select id into roleid from acc_private.server_roles where server=s and everyone;
 perform public.acc_call('serverChannelRule',jsonb_build_object('server',s,'room',r,'role',roleid,'permissions','{"view":false,"post":false}'::jsonb));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if acc_private.access(r) then raise exception 'Channel deny bypass';end if;
 begin perform public.acc_call('send',jsonb_build_object('room',r,'body','Forbidden server post','nonce',gen_random_uuid()));raise exception 'Post deny bypass';exception when others then if sqlerrm='Post deny bypass' then raise;end if;end;
 begin perform public.acc_call('rename',jsonb_build_object('room',r,'name','Legacy bypass'));raise exception 'Legacy server edit bypass';exception when others then if sqlerrm='Legacy server edit bypass' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('serverChannelRule',jsonb_build_object('server',s,'room',r,'role',roleid,'permissions','{}'::jsonb));
 perform public.acc_call('serverModerate',jsonb_build_object('server',s,'target',student,'banned',true));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if acc_private.access(r) then raise exception 'Ban did not revoke access';end if;
 begin perform public.acc_call('serverJoin',jsonb_build_object('server',s));raise exception 'Banned member rejoined';exception when others then if sqlerrm='Banned member rejoined' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('serverModerate',jsonb_build_object('server',s,'target',student,'banned',false));
 update public.acc_servers set visibility='private' where id=s;delete from acc_private.server_members where server=s and person=student;
 v:=public.acc_call('serverInvite',jsonb_build_object('server',s));code:=v->>'code';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 begin perform public.acc_call('serverJoin',jsonb_build_object('server',s,'code','wrong'));raise exception 'Wrong invite accepted';exception when others then if sqlerrm='Wrong invite accepted' then raise;end if;end;
 perform public.acc_call('serverJoin',jsonb_build_object('server',s,'code',code));
 if not acc_private.access(r) then raise exception 'Valid invitation failed';end if;
 perform public.acc_call('serverLeave',jsonb_build_object('server',s));
 begin perform public.acc_call('serverJoin',jsonb_build_object('server',s,'code',code));raise exception 'Spent invitation reused';exception when others then if sqlerrm='Spent invitation reused' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('serverDelete',jsonb_build_object('server',s,'confirm','Rollback server'));
 if exists(select 1 from public.acc_rooms where id=r) or exists(select 1 from acc_private.server_channels where server=s) then raise exception 'Server deletion orphaned rooms';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
end $$;
set local role authenticated;
do $$begin if exists(select 1 from public.acc_messages where room=current_setting('sv.room')::uuid) then raise exception 'Private room RLS leak';end if;if has_function_privilege(current_user,'acc_private.manage_notifications(text,jsonb)','EXECUTE') then raise exception 'Old dispatch bypass available';end if;end $$;
reset role;
rollback;
select 'PASS rollback-only two real account contexts: pilot gate, creation rate limit, approval, private invitations/single use, channel deny, post deny, legacy edit denial, platform-role isolation, bans, direct RLS. No browser authentication or live two-client claim.' result;
